}

// --- Loader (upstream components/loader.ts) ---------------------------------

/// Fixed frame 0 of the default spinner: `Loader::new` starts the animation
/// thread with an 80ms first tick, so stopping immediately pins the frame
/// deterministically at 0.
#[test]
fn loader_frame0() {
    let mut loader = Loader::new(
        RenderHandle::new(|| {}),
        cyan,
        std::string::ToString::to_string,
        "Loading…",
        None,
    );
